import UIKit

// [EN] FIX: issue #535 — tap animations of tab buttons and the plus button, translated from Objective-C (docs/Swift-Migration.md,
//      step 46). The protocol and the classes keep their Objective-C names and selectors, and their Swift names (the
//      underscored `cyl_play…` names are the ones Swift imported from the header; apps' conformances stay valid).
//      Objective-C callers get them from the generated Swift interface (`CYLSwiftInterface.h`), through CYLTabButtonAnimation.h.
//      Ported from the TLAnimationTabBar animations (themselves ported from Ramotion's animated-tab-bar, MIT).
// [CN] Tab 按钮与 PlusButton 的点击动画，已从 Objective-C 翻译（docs/Swift-Migration.md，第 46 步）。协议与类保留 Objective-C 名称、
//      selector 以及 Swift 名称（带下划线的 `cyl_play…` 名称就是 Swift 以前从头文件导入的名称，App 的实现仍然有效）。Objective-C 调用方
//      通过 CYLTabButtonAnimation.h 从 Swift 生成接口（`CYLSwiftInterface.h`）获得声明。移植自 TLAnimationTabBar（其本身移植自 Ramotion 的
//      animated-tab-bar，MIT 协议）。

/**
 * [EN] The signature of the animation blocks of `CYLTabButtonBlockAnimation`: the same arguments as the protocol methods.
 * [CN] `CYLTabButtonBlockAnimation` 中动画 block 的签名：参数与协议方法相同。
 */
public typealias CYLTabButtonAnimationBlock = (UIControl, UIView, UILabel?) -> Void

/**
 * [EN] The signature of `CYLTabButtonBlockAnimation.badgeChangedAnimation`.
 * [CN] `CYLTabButtonBlockAnimation.badgeChangedAnimation` 的签名。
 */
public typealias CYLTabButtonBadgeAnimationBlock = (UIControl, UIView, UIView?) -> Void

/**
 * [EN] A tap animation of a tab button or plus button, played when the button is selected (a tap, a repeated tap, or a
 *      change of `selectedIndex` in code), in every style. `button` is the tab button (or the plus button), `iconView` its
 *      image view (the Lottie view when the tab has one) and `titleLabel` its title label, nil when it has none. In
 *      Liquid Glass the selected layer is animated too, so a method can be called twice for one tap. Every method comes
 *      in two spellings that run the same logic, `cyl_play…` and `cylPlay…`; when both are implemented, `cylPlay…` is called.
 * [CN] Tab 按钮或 PlusButton 的点击动画，按钮被选中时（点击、再次点击，或代码修改 `selectedIndex`）播放，适用于所有样式。`button` 为
 *      Tab 按钮（或 PlusButton），`iconView` 为其图片视图（有 Lottie 时为 Lottie 视图），`titleLabel` 为其标题，没有时为 nil。液态玻璃下
 *      选中图层也会播放，因此一次点击可能调用两次。每个方法都有 `cyl_play…` 与 `cylPlay…` 两种写法，执行相同逻辑；都实现时调用 `cylPlay…`。
 */
@objc(CYLTabButtonAnimation)
public protocol CYLTabButtonAnimation: NSObjectProtocol {

    /**
     * [EN] Plays the animation of a button that is being selected.
     * [CN] 播放按钮被选中时的动画。
     */
    @objc(cyl_playSelectAnimationWithTabButton:iconView:titleLabel:)
    optional func cyl_playSelectAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?)

    /**
     * [EN] `cyl_playSelectAnimation(withTabButton:…)` without the underscore.
     * [CN] 去掉下划线的 `cyl_playSelectAnimation(withTabButton:…)`。
     */
    @objc(cylPlaySelectAnimationWithTabButton:iconView:titleLabel:)
    optional func cylPlaySelectAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?)

    /**
     * [EN] `cyl_playDeselectAnimation(withTabButton:…)` without the underscore.
     * [CN] 去掉下划线的 `cyl_playDeselectAnimation(withTabButton:…)`。
     */
    @objc(cylPlayDeselectAnimationWithTabButton:iconView:titleLabel:)
    optional func cylPlayDeselectAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?)

    /**
     * [EN] `cyl_playReselectAnimation(withTabButton:…)` without the underscore.
     * [CN] 去掉下划线的 `cyl_playReselectAnimation(withTabButton:…)`。
     */
    @objc(cylPlayReselectAnimationWithTabButton:iconView:titleLabel:)
    optional func cylPlayReselectAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?)

    /**
     * [EN] `cyl_playHighlightAnimation(withTabButton:…)` without the underscore.
     * [CN] 去掉下划线的 `cyl_playHighlightAnimation(withTabButton:…)`。
     */
    @objc(cylPlayHighlightAnimationWithTabButton:iconView:titleLabel:)
    optional func cylPlayHighlightAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?)

    /**
     * [EN] `cyl_playDehighlightAnimation(withTabButton:…)` without the underscore.
     * [CN] 去掉下划线的 `cyl_playDehighlightAnimation(withTabButton:…)`。
     */
    @objc(cylPlayDehighlightAnimationWithTabButton:iconView:titleLabel:)
    optional func cylPlayDehighlightAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?)

    /**
     * [EN] `cyl_playBadgeChangedAnimation(withTabButton:…)` without the underscore.
     * [CN] 去掉下划线的 `cyl_playBadgeChangedAnimation(withTabButton:…)`。
     */
    @objc(cylPlayBadgeChangedAnimationWithTabButton:iconView:badgeView:)
    optional func cylPlayBadgeChangedAnimation(withTabButton button: UIControl, iconView: UIView, badgeView: UIView?)

    /**
     * [EN] Plays the animation of the button that was selected before (when another button gets selected).
     * [CN] 播放之前选中的按钮（在另一个按钮被选中时）的取消选中动画。
     */
    @objc(cyl_playDeselectAnimationWithTabButton:iconView:titleLabel:)
    optional func cyl_playDeselectAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?)

    /**
     * [EN] Undoes what this animation left on the button (a held frame, a hidden title, a moved icon) when another animation
     *      takes over the button.
     * [CN] 当其他动画接管该按钮时，撤销本动画在按钮上留下的状态（保持的帧、隐藏的标题、移动过的图标）。
     */
    @objc(cyl_resetTabButton:iconView:titleLabel:)
    optional func cyl_resetTabButton(_ button: UIControl, iconView: UIView, titleLabel: UILabel?)

    /**
     * [EN] Set before the select animation: true when the button selected before is on the left of this one.
     * [CN] 在选中动画之前设置：之前选中的按钮位于本按钮左侧时为 true。
     */
    @objc(cyl_fromLeft)
    optional var cyl_fromLeft: Bool { @objc(cyl_isFromLeft) get @objc(cyl_setFromLeft:) set }

    /**
     * [EN] Set before the deselect animation: true when the button selected next is on the right of this one.
     * [CN] 在取消选中动画之前设置：下一个选中的按钮位于本按钮右侧时为 true。
     */
    @objc(cyl_toRight)
    optional var cyl_toRight: Bool { @objc(cyl_isToRight) get @objc(cyl_setToRight:) set }

    /**
     * [EN] Plays the animation of a button tapped again while selected; when not implemented the select animation plays again.
     * [CN] 再次点击已选中按钮时的动画；未实现时再次播放选中动画。
     */
    @objc(cyl_playReselectAnimationWithTabButton:iconView:titleLabel:)
    optional func cyl_playReselectAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?)

    /**
     * [EN] Plays the animation of a button a finger went down on (pressed), in every style.
     * [CN] 手指按下按钮（按压）时的动画，适用于所有样式。
     */
    @objc(cyl_playHighlightAnimationWithTabButton:iconView:titleLabel:)
    optional func cyl_playHighlightAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?)

    /**
     * [EN] Plays the animation of a pressed button the finger lifted from, or whose touch was cancelled.
     * [CN] 按压的手指抬起或触摸被取消时的动画。
     */
    @objc(cyl_playDehighlightAnimationWithTabButton:iconView:titleLabel:)
    optional func cyl_playDehighlightAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?)

    /**
     * [EN] Plays the animation of a button whose badge appeared or changed; `badgeView` is the badge UIKit draws, nil when
     *      it cannot be found. Called on the next run loop turn.
     * [CN] 按钮的角标出现或变化时的动画；`badgeView` 为 UIKit 绘制的角标，找不到时为 nil。在下一个 runloop 调用。
     */
    @objc(cyl_playBadgeChangedAnimationWithTabButton:iconView:badgeView:)
    optional func cyl_playBadgeChangedAnimation(withTabButton button: UIControl, iconView: UIView, badgeView: UIView?)
}

// MARK: - Helpers

/**
 * [EN] The shared pieces of the animations below.
 * [CN] 下面各动画共用的部分。
 */
enum CYLTabButtonAnimationKit {
    /** [EN] Duration of the TLAnimationTabBar animations. [CN] TLAnimationTabBar 动画的时长。 */
    static let duration: TimeInterval = 0.5
    /** [EN] The held frames of `CYLTabButtonFrameAnimation`. [CN] `CYLTabButtonFrameAnimation` 保持的帧。 */
    static let frameAnimationKey = "cyl.tabButton.frames"

    /** [EN] A cubic keyframe animation. [CN] 三次曲线插值的关键帧动画。 */
    static func keyframe(_ keyPath: String, _ values: [Any], duration: TimeInterval = duration) -> CAKeyframeAnimation {
        let animation = CAKeyframeAnimation(keyPath: keyPath)
        animation.values = values
        animation.duration = duration
        animation.calculationMode = .cubic
        return animation
    }

    static func playFrames(on iconView: UIView, images: [UIImage], reversed: Bool) {
        let frames = (reversed ? images.reversed() : images).compactMap { $0.cgImage }
        guard !frames.isEmpty else { return }
        let animation = keyframe("contents", frames)
        animation.calculationMode = .discrete
        animation.repeatCount = 1
        // [EN] Selected: the last frame stays. Deselected (reversed): back to the icon itself at the end.
        // [CN] 选中：保持最后一帧。取消选中（倒序）：结束后恢复为图标本身。
        animation.isRemovedOnCompletion = reversed
        animation.fillMode = reversed ? .removed : .forwards
        iconView.layer.add(animation, forKey: frameAnimationKey)
    }

    /** [EN] A small dot drawn in `color`, the default firework particle. [CN] 用 `color` 绘制的小圆点，默认的烟花粒子。 */
    static func dotImage(_ color: UIColor) -> UIImage {
        let size = CGSize(width: 8, height: 8)
        return UIGraphicsImageRenderer(size: size).image { _ in
            color.setFill()
            UIBezierPath(ovalIn: CGRect(origin: .zero, size: size)).fill()
        }
    }

    /**
     * [EN] `image` drawn into a bitmap for an emitter cell (a CGImage has no tint): a template image in `tintColor`.
     * [CN] 将 `image` 绘制为位图供粒子使用（CGImage 不含着色）：模板图片按 `tintColor` 绘制。
     */
    static func particleImage(_ image: UIImage, tintColor: UIColor) -> UIImage {
        guard image.size.width > 0, image.size.height > 0 else { return image }
        let format = UIGraphicsImageRendererFormat.preferred()
        format.opaque = false
        return UIGraphicsImageRenderer(size: image.size, format: format).image { context in
            let rect = CGRect(origin: .zero, size: image.size)
            if image.renderingMode == .alwaysTemplate {
                tintColor.setFill()
                image.draw(in: rect)
                context.cgContext.setBlendMode(.sourceIn)
                context.cgContext.fill(rect)
            } else {
                image.draw(in: rect)
            }
        }
    }

    // swiftlint:disable:next function_parameter_count
    static func emitterLayer(_ cellName: String, lifetime: Float, lifetimeRange: Float, velocity: CGFloat,
                             velocityRange: CGFloat, image: UIImage, center: CGPoint) -> CAEmitterLayer {
        let cell = CAEmitterCell()
        cell.name = cellName
        cell.alphaRange = 0.20
        cell.alphaSpeed = -1.0
        cell.lifetime = lifetime
        cell.lifetimeRange = lifetimeRange
        cell.birthRate = 0
        cell.velocity = velocity
        cell.velocityRange = velocityRange
        cell.contents = image.cgImage
        cell.scale = 0.5
        cell.scaleRange = 0.2
        let layer = CAEmitterLayer()
        layer.name = "cyl_emitterLayer"
        layer.emitterShape = .circle
        layer.emitterMode = .outline
        layer.emitterSize = CGSize(width: 25, height: 0)
        layer.emitterCells = [cell]
        layer.renderMode = .oldestFirst
        layer.masksToBounds = false
        layer.emitterPosition = center
        return layer
    }

    /**
     * [EN] Fireworks around `view`: particles gather, then burst; the emitter layers are removed after.
     * [CN] `view` 周围的烟花：粒子先聚拢再炸开，结束后移除粒子图层。
     */
    static func playFireworks(on view: UIView, image: UIImage?) {
        let tintColor: UIColor = view.tintColor ?? .systemBlue
        let particle = image.map { particleImage($0, tintColor: tintColor) } ?? dotImage(tintColor)
        guard particle.cgImage != nil else { return }
        let clipsToBounds = view.clipsToBounds
        view.clipsToBounds = false
        let center = CGPoint(x: view.bounds.midX, y: view.bounds.midY)
        let explosionLayer = emitterLayer("explosion", lifetime: 0.7, lifetimeRange: 0.3, velocity: 40, velocityRange: 10,
                                          image: particle, center: center)
        let chargeLayer = emitterLayer("charge", lifetime: 0.3, lifetimeRange: 0.1, velocity: -40, velocityRange: 0,
                                       image: particle, center: center)
        view.layer.addSublayer(explosionLayer)
        view.layer.addSublayer(chargeLayer)
        chargeLayer.beginTime = CACurrentMediaTime()
        chargeLayer.setValue(100, forKeyPath: "emitterCells.charge.birthRate")
        DispatchQueue.main.asyncAfter(deadline: .now() + duration) { [weak view] in
            chargeLayer.setValue(0, forKeyPath: "emitterCells.charge.birthRate")
            chargeLayer.removeFromSuperlayer()
            explosionLayer.beginTime = CACurrentMediaTime()
            explosionLayer.setValue(300, forKeyPath: "emitterCells.explosion.birthRate")
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) {
                explosionLayer.setValue(0, forKeyPath: "emitterCells.explosion.birthRate")
                explosionLayer.removeFromSuperlayer()
                view?.clipsToBounds = clipsToBounds
            }
        }
    }
}

// MARK: - Animations

/**
 * [EN] Scale up then down: 1.0 → 1.5 → 0.8 → 1.0 (the "点击放大再缩小" animation of issue #535).
 * [CN] 放大再缩小：1.0 → 1.5 → 0.8 → 1.0（issue #535 中的“点击放大再缩小”）。
 */
@objc(CYLTabButtonScaleAnimation)
open class CYLTabButtonScaleAnimation: NSObject, CYLTabButtonAnimation {
    /**
     * [EN] Default 0.5 s.
     * [CN] 默认 0.5 秒。
     */
    @objc open var duration: TimeInterval = CYLTabButtonAnimationKit.duration

    @objc(cyl_playSelectAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playSelectAnimation(withTabButton _: UIControl, iconView: UIView, titleLabel _: UILabel?) {
        // [EN] Layer keyframes, so a transform the tab bar set on the icon is left alone.
        // [CN] 使用图层关键帧动画，不会覆盖 TabBar 设置在图标上的 transform。
        let animation = CAKeyframeAnimation(keyPath: "transform.scale")
        animation.values = [1.0, 1.5, 0.8, 1.0]
        animation.keyTimes = [0, NSNumber(value: 1.0 / 3.0), NSNumber(value: 2.0 / 3.0), 1]
        animation.duration = duration
        iconView.layer.add(animation, forKey: "cyl.tabButton.scale")
    }
}

/**
 * [EN] The icon grows from small to its size with a slight overshoot (the "图片从小放大" animation of issue #535).
 * [CN] 图标从小放大到原尺寸并略微回弹（issue #535 中的“图片从小放大”）。
 */
@objc(CYLTabButtonZoomInAnimation)
open class CYLTabButtonZoomInAnimation: NSObject, CYLTabButtonAnimation {
    /**
     * [EN] Default 0.5 s.
     * [CN] 默认 0.5 秒。
     */
    @objc open var duration: TimeInterval = CYLTabButtonAnimationKit.duration

    @objc(cyl_playSelectAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playSelectAnimation(withTabButton _: UIControl, iconView: UIView, titleLabel _: UILabel?) {
        let animation = CAKeyframeAnimation(keyPath: "transform.scale")
        animation.values = [0.1, 1.2, 0.9, 1.0]
        animation.keyTimes = [0, 0.5, 0.75, 1]
        animation.duration = duration
        iconView.layer.add(animation, forKey: "cyl.tabButton.zoomIn")
    }
}

/**
 * [EN] Elastic bounce of the icon (TLBounceAnimation), optionally with fireworks.
 * [CN] 图标弹性动画（TLBounceAnimation），可选烟花效果。
 */
@objc(CYLTabButtonBounceAnimation)
open class CYLTabButtonBounceAnimation: NSObject, CYLTabButtonAnimation {
    /**
     * [EN] Plays fireworks around the icon. Default false.
     * [CN] 是否在图标周围播放烟花效果，默认 false。
     */
    @objc open var playsFireworks = false

    /**
     * [EN] The firework particle; nil: a small dot in the button's tint color.
     * [CN] 烟花粒子图片；nil 时为按钮 tintColor 的小圆点。
     */
    @objc open var fireworksImage: UIImage?

    @objc(cyl_playSelectAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playSelectAnimation(withTabButton _: UIControl, iconView: UIView, titleLabel _: UILabel?) {
        let animation = CYLTabButtonAnimationKit.keyframe("transform.scale", [1.0, 0.85, 1.15, 0.95, 1.02, 1.0])
        iconView.layer.add(animation, forKey: "cyl.tabButton.bounce")
        if playsFireworks {
            CYLTabButtonAnimationKit.playFireworks(on: iconView, image: fireworksImage)
        }
    }
}

/**
 * [EN] One full turn of the icon (TLRotationAnimation).
 * [CN] 图标旋转一圈（TLRotationAnimation）。
 */
@objc(CYLTabButtonRotationAnimation)
open class CYLTabButtonRotationAnimation: NSObject, CYLTabButtonAnimation {
    @objc(cyl_playSelectAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playSelectAnimation(withTabButton _: UIControl, iconView: UIView, titleLabel _: UILabel?) {
        let animation = CABasicAnimation(keyPath: "transform.rotation")
        animation.fromValue = 0.0
        animation.toValue = -Double.pi * 2
        animation.duration = CYLTabButtonAnimationKit.duration
        iconView.layer.add(animation, forKey: "cyl.tabButton.rotation")
    }
}

/**
 * [EN] The icon moves down while the title floats up and fades out; deselecting brings them back (TLFumeAnimation).
 *      The title stays hidden while the tab is selected.
 * [CN] 图标下移，标题上浮并淡出；取消选中时恢复（TLFumeAnimation）。Tab 选中期间标题保持隐藏。
 */
@objc(CYLTabButtonFumeAnimation)
open class CYLTabButtonFumeAnimation: NSObject, CYLTabButtonAnimation {
    // [EN] The animations Fume leaves on the button while it is selected. [CN] Tab 选中期间 Fume 留在按钮上的动画。
    private static let iconKey = "cyl.tabButton.fume.icon"
    private static let moveKey = "cyl.tabButton.fume.move"
    private static let scaleKey = "cyl.tabButton.fume.scale"
    private static let opacityKey = "cyl.tabButton.fume.opacity"

    private static func moveIcon(_ iconView: UIView, _ values: [CGFloat]) {
        let animation = CYLTabButtonAnimationKit.keyframe("position.y", values, duration: CYLTabButtonAnimationKit.duration / 2)
        animation.fillMode = .forwards
        animation.isRemovedOnCompletion = false
        iconView.layer.add(animation, forKey: iconKey)
    }

    @objc(cyl_playSelectAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playSelectAnimation(withTabButton _: UIControl, iconView: UIView, titleLabel: UILabel?) {
        let iconY = iconView.layer.position.y
        Self.moveIcon(iconView, [iconY, iconY + 4])
        guard let titleLabel else { return }
        let y = titleLabel.layer.position.y
        titleLabel.layer.add(CYLTabButtonAnimationKit.keyframe("position.y", [y, y - 60]), forKey: Self.moveKey)
        titleLabel.layer.add(CYLTabButtonAnimationKit.keyframe("transform.scale", [1.0, 2.0]), forKey: Self.scaleKey)
        titleLabel.layer.add(CYLTabButtonAnimationKit.keyframe("opacity", [1.0, 0.0]), forKey: Self.opacityKey)
        titleLabel.alpha = 0
    }

    @objc(cyl_playDeselectAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playDeselectAnimation(withTabButton _: UIControl, iconView: UIView, titleLabel: UILabel?) {
        // [EN] Removing the forward-filled move puts the icon back where the layout placed it.
        // [CN] 移除保持在终点的位移动画，图标回到布局给出的位置。
        iconView.layer.removeAnimation(forKey: Self.iconKey)
        guard let titleLabel else { return }
        let y = titleLabel.layer.position.y
        titleLabel.layer.add(CYLTabButtonAnimationKit.keyframe("position.y", [y + 15, y]), forKey: Self.moveKey)
        titleLabel.layer.add(CYLTabButtonAnimationKit.keyframe("opacity", [0.0, 1.0]), forKey: Self.opacityKey)
        titleLabel.alpha = 1
    }

    @objc(cyl_resetTabButton:iconView:titleLabel:)
    open func cyl_resetTabButton(_: UIControl, iconView: UIView, titleLabel: UILabel?) {
        iconView.layer.removeAnimation(forKey: Self.iconKey)
        for key in [Self.moveKey, Self.scaleKey, Self.opacityKey] {
            titleLabel?.layer.removeAnimation(forKey: key)
        }
        titleLabel?.alpha = 1
    }
}

/**
 * [EN] The icon shrinks while the button is pressed and springs back when the finger lifts; no select animation.
 * [CN] 按压时图标缩小，手指抬起时弹回；没有选中动画。
 */
@objc(CYLTabButtonPressAnimation)
open class CYLTabButtonPressAnimation: NSObject, CYLTabButtonAnimation {
    /**
     * [EN] The icon's scale while pressed. Default 0.85.
     * [CN] 按压时图标的缩放比例，默认 0.85。
     */
    @objc open var pressedScale: CGFloat = 0.85

    @objc(cyl_playSelectAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playSelectAnimation(withTabButton _: UIControl, iconView _: UIView, titleLabel _: UILabel?) {
        // [EN] Pressing is the whole animation; nothing more on selection. [CN] 按压即是全部动画，选中时不再播放。
    }

    @objc(cyl_playHighlightAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playHighlightAnimation(withTabButton _: UIControl, iconView: UIView, titleLabel _: UILabel?) {
        let scale = pressedScale
        UIView.animate(withDuration: 0.12, delay: 0, options: [.beginFromCurrentState, .allowUserInteraction]) {
            iconView.transform = CGAffineTransform(scaleX: scale, y: scale)
        }
    }

    @objc(cyl_playDehighlightAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playDehighlightAnimation(withTabButton _: UIControl, iconView: UIView, titleLabel _: UILabel?) {
        UIView.animate(withDuration: 0.35, delay: 0, usingSpringWithDamping: 0.5, initialSpringVelocity: 0,
                       options: [.beginFromCurrentState, .allowUserInteraction]) {
            iconView.transform = .identity
        }
    }
}

/**
 * [EN] A `CYLTabButtonAnimation` made of blocks (Swift closures): each block plays the matching protocol method. A block left
 *      nil behaves as if the method were not implemented, so the library's default applies.
 * [CN] 由 block（Swift 闭包）组成的 `CYLTabButtonAnimation`：每个 block 对应播放同名协议方法。为 nil 的 block 等同于未实现该方法，
 *      库的默认行为生效。
 */
@objc(CYLTabButtonBlockAnimation)
open class CYLTabButtonBlockAnimation: NSObject, CYLTabButtonAnimation {
    /**
     * [EN] `cyl_playSelectAnimation(withTabButton:…)`; nil plays nothing.
     * [CN] `cyl_playSelectAnimation(withTabButton:…)`；nil 时不播放。
     */
    @objc open var selectAnimation: CYLTabButtonAnimationBlock?
    /**
     * [EN] `cyl_playDeselectAnimation(withTabButton:…)`.
     * [CN] `cyl_playDeselectAnimation(withTabButton:…)`。
     */
    @objc open var deselectAnimation: CYLTabButtonAnimationBlock?
    /**
     * [EN] `cyl_playReselectAnimation(withTabButton:…)`.
     * [CN] `cyl_playReselectAnimation(withTabButton:…)`。
     */
    @objc open var reselectAnimation: CYLTabButtonAnimationBlock?
    /**
     * [EN] `cyl_playHighlightAnimation(withTabButton:…)` (finger down).
     * [CN] `cyl_playHighlightAnimation(withTabButton:…)`（手指按下）。
     */
    @objc open var highlightAnimation: CYLTabButtonAnimationBlock?
    /**
     * [EN] `cyl_playDehighlightAnimation(withTabButton:…)` (finger up).
     * [CN] `cyl_playDehighlightAnimation(withTabButton:…)`（手指抬起）。
     */
    @objc open var dehighlightAnimation: CYLTabButtonAnimationBlock?
    /**
     * [EN] `cyl_playBadgeChangedAnimation(withTabButton:…)`.
     * [CN] `cyl_playBadgeChangedAnimation(withTabButton:…)`。
     */
    @objc open var badgeChangedAnimation: CYLTabButtonBadgeAnimationBlock?

    /**
     * [EN] An optional method counts as implemented only while its block is set.
     * [CN] 只有设置了对应 block 时，可选方法才算已实现。
     */
    open override func responds(to aSelector: Selector!) -> Bool {
        switch aSelector {
        case #selector(cyl_playDeselectAnimation(withTabButton:iconView:titleLabel:)): return deselectAnimation != nil
        case #selector(cyl_playReselectAnimation(withTabButton:iconView:titleLabel:)): return reselectAnimation != nil
        case #selector(cyl_playHighlightAnimation(withTabButton:iconView:titleLabel:)): return highlightAnimation != nil
        case #selector(cyl_playDehighlightAnimation(withTabButton:iconView:titleLabel:)): return dehighlightAnimation != nil
        case #selector(cyl_playBadgeChangedAnimation(withTabButton:iconView:badgeView:)): return badgeChangedAnimation != nil
        default: return super.responds(to: aSelector)
        }
    }

    @objc(cyl_playSelectAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playSelectAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?) {
        selectAnimation?(button, iconView, titleLabel)
    }

    @objc(cyl_playDeselectAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playDeselectAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?) {
        deselectAnimation?(button, iconView, titleLabel)
    }

    @objc(cyl_playReselectAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playReselectAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?) {
        reselectAnimation?(button, iconView, titleLabel)
    }

    @objc(cyl_playHighlightAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playHighlightAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?) {
        highlightAnimation?(button, iconView, titleLabel)
    }

    @objc(cyl_playDehighlightAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playDehighlightAnimation(withTabButton button: UIControl, iconView: UIView, titleLabel: UILabel?) {
        dehighlightAnimation?(button, iconView, titleLabel)
    }

    @objc(cyl_playBadgeChangedAnimationWithTabButton:iconView:badgeView:)
    open func cyl_playBadgeChangedAnimation(withTabButton button: UIControl, iconView: UIView, badgeView: UIView?) {
        badgeChangedAnimation?(button, iconView, badgeView)
    }
}

/**
 * [EN] Flips or curls the icon (TLTransitionAniamtion). `direction` 1–6: flip from left, flip from right, flip from top,
 *      flip from bottom, curl up, curl down (default 1).
 * [CN] 翻转或卷页动画（TLTransitionAniamtion）。`direction` 取值 1–6：从左翻转、从右翻转、从上翻转、从下翻转、向上卷页、向下卷页（默认 1）。
 */
@objc(CYLTabButtonFlipAnimation)
open class CYLTabButtonFlipAnimation: NSObject, CYLTabButtonAnimation {
    /**
     * [EN] 1–6, see the class comment. Default 1.
     * [CN] 1–6，见类注释。默认 1。
     */
    @objc open var direction: Int = 1

    /**
     * [EN] No animation when the button is deselected. Default false.
     * [CN] 取消选中时不播放动画，默认 false。
     */
    @objc open var disablesDeselectAnimation = false

    private var clampedDirection: Int {
        min(max(direction, 1), 6)
    }

    /** [EN] The transition option for `direction` 1–6. [CN] `direction`（1–6）对应的转场选项。 */
    private static func option(_ direction: Int) -> UIView.AnimationOptions {
        switch direction {
        case 2: return .transitionFlipFromRight
        case 3: return .transitionFlipFromTop
        case 4: return .transitionFlipFromBottom
        case 5: return .transitionCurlUp
        case 6: return .transitionCurlDown
        default: return .transitionFlipFromLeft
        }
    }

    @objc(cyl_playSelectAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playSelectAnimation(withTabButton _: UIControl, iconView: UIView, titleLabel _: UILabel?) {
        UIView.transition(with: iconView, duration: CYLTabButtonAnimationKit.duration, options: Self.option(clampedDirection),
                          animations: nil)
    }

    @objc(cyl_playDeselectAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playDeselectAnimation(withTabButton _: UIControl, iconView: UIView, titleLabel _: UILabel?) {
        guard !disablesDeselectAnimation else { return }
        // [EN] The opposite direction: 1 ↔ 2, 3 ↔ 4, 5 ↔ 6. [CN] 反方向：1 ↔ 2、3 ↔ 4、5 ↔ 6。
        let direction = clampedDirection
        let opposite = direction % 2 == 0 ? direction - 1 : direction + 1
        UIView.transition(with: iconView, duration: CYLTabButtonAnimationKit.duration, options: Self.option(opposite),
                          animations: nil)
    }
}

/**
 * [EN] Plays `images` as frames on the icon and keeps the last one while selected; when deselected, plays them in reverse,
 *      then shows the icon itself again (TLFrameAnimation).
 * [CN] 在图标上逐帧播放 `images`，选中期间保持最后一帧；取消选中时倒序播放，结束后恢复显示图标本身（TLFrameAnimation）。
 */
@objc(CYLTabButtonFrameAnimation)
open class CYLTabButtonFrameAnimation: NSObject, CYLTabButtonAnimation {
    /**
     * [EN] The frames.
     * [CN] 帧图片。
     */
    @objc open var images: [UIImage]?

    /**
     * [EN] Plays fireworks around the icon. Default false.
     * [CN] 是否在图标周围播放烟花效果，默认 false。
     */
    @objc open var playsFireworks = false

    /**
     * [EN] The firework particle; nil: a small dot in the button's tint color.
     * [CN] 烟花粒子图片；nil 时为按钮 tintColor 的小圆点。
     */
    @objc open var fireworksImage: UIImage?

    @objc(cyl_playSelectAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playSelectAnimation(withTabButton _: UIControl, iconView: UIView, titleLabel _: UILabel?) {
        guard let images, !images.isEmpty else { return }
        CYLTabButtonAnimationKit.playFrames(on: iconView, images: images, reversed: false)
        if playsFireworks {
            CYLTabButtonAnimationKit.playFireworks(on: iconView, image: fireworksImage)
        }
    }

    @objc(cyl_playDeselectAnimationWithTabButton:iconView:titleLabel:)
    open func cyl_playDeselectAnimation(withTabButton _: UIControl, iconView: UIView, titleLabel _: UILabel?) {
        guard let images, !images.isEmpty else { return }
        CYLTabButtonAnimationKit.playFrames(on: iconView, images: images, reversed: true)
    }

    @objc(cyl_resetTabButton:iconView:titleLabel:)
    open func cyl_resetTabButton(_: UIControl, iconView: UIView, titleLabel _: UILabel?) {
        iconView.layer.removeAnimation(forKey: CYLTabButtonAnimationKit.frameAnimationKey)
    }
}
